    padding: 50px 60px !important;
    font-size: 16px;
    text-align: center;
    margin: 0px auto !important;
}

.lp-footer{
    background-color: #ebebeb;
    color: #3d3d3d;
    max-width: 100% !important;
    border-top: 15px solid #c09f53;
}

.links{
    color: #c09f53;
    text-decoration: none;
}

.footer-logo{
    width: 300px;
    object-fit: contain;
    margin: 0 auto;
}

.footer-nav-container{
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 20px;
    margin: 20px auto;
    max-width: 350px;
}

.footer-nav{
    display: flex;
    gap: 20px;
    flex-wrap: wrap;
    flex-direction: column;;
}

.footer-logo-container{
    margin-top: 80px;
}

.footer.lp-footer a {
    color: #717171;
}

.footer.lp-footer a:hover {
    color: #c09f53;
}

.copy-info{
    font-size: 14px;
    color: #717171;
}

@media screen and (max-width: 900px) {
    .footer-nav-container{
        grid-template-columns: 1fr;
    }
    .footer-nav{
        justify-content: center;
        gap: 10px;
    }
    .footer-logo-container{
        margin-top: 20px;
    }
    
