    padding: 0 24px 24px;
}

.experiments-page h1 {
    margin-bottom: 24px;
    color: #e0e0e0;
}

.experiments-loading,
.experiments-error,
.experiments-empty {
    color: #a0a0a0;
    margin-top: 16px;
}

.experiments-empty {
    margin-top: 24px;
    text-align: center;
    font-size: 1.2rem;
    font-weight: 600;
    color: #a0a0a0;
    line-height: 1.5;
    padding: 24px;
    border: 1px solid rgba(255, 255, 255, 0.08);
    border-radius: 10px;
}

.experiments-error {
    color: #e08080;
}

.experiments-list {
    margin-top: 24px;
}

.experiments-list-intro {
    color: #a0a0a0;
    margin-bottom: 16px;
}

.experiments-id-list {
    list-style: none;
    margin: 0;
    padding: 0;
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.experiments-id-link {
    display: block;
    padding: 12px 16px;
    background: rgba(255, 255, 255, 0.06);
    border-radius: 8px;
    color: #b0d4ff;
    text-decoration: none;
    font-weight: 500;
    transition: background 0.2s;
}

.experiments-id-link:hover {
    background: rgba(255, 255, 255, 0.12);
    color: #c8e0ff;
}

.experiments-back {
    margin-left: 12px;
    padding: 6px 12px;
    font-size: 0.9rem;
    color: #a0a0a0;
    background: transparent;
    border: 1px solid rgba(255, 255, 255, 0.2);
    border-radius: 6px;
    cursor: pointer;
}

.experiments-back:hover {
    color: #e0e0e0;
    border-color: rgba(255, 255, 255, 0.35);
}

.experiments-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));
    gap: 24px;
}

.experiment-card {
    background: radial-gradient(circle at top, rgb(101, 101, 101) -10%, rgb(48, 48, 48));
    border-radius: 10px;
    padding: 20px;
    box-shadow: 0 0 3px 0 rgba(0, 0, 0, 0.22);
    color: rgb(197, 197, 197);
    display: flex;
    flex-direction: column;
    gap: 20px;
}

.experiment-card__header {
    display: flex;
    flex-wrap: wrap;
    align-items: baseline;
    gap: 10px;
    padding-bottom: 12px;
    border-bottom: 1px solid rgba(255, 255, 255, 0.1);
}

.experiment-card__variant {
    margin: 0;
    font-size: 1.25rem;
    font-weight: 600;
    color: #e0e0e0;
}

.experiment-card__design {
    font-size: 0.85rem;
    color: #a8a8a8;
    background: rgba(255, 255, 255, 0.08);
    padding: 4px 10px;
    border-radius: 6px;
}

.experiment-card__donuts {
    display: flex;
    gap: 50px;
    justify-content: center;
    align-items: flex-end;
    flex-wrap: wrap;
    padding: 12px 0;
    border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}

.experiment-card__donut-wrap {
    position: relative;
    width: 100px;
    height: 150px;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 6px;
}

.experiment-card__donut-wrap canvas {
    max-height: 100px;
}

.experiment-card__donut-label {
    font-size: 0.7rem;
    color: #a0a0a0;
    text-transform: uppercase;
    letter-spacing: 0.04em;
    width: max-content;
}

.experiments-filters {
    display: flex;
    gap: 10px;
    align-items: center;
    justify-content: flex-end;
}

.experiment-card--winning {
    border: 2px solid rgba(76, 175, 80, 0.8);
    box-shadow: 0 0 16px rgba(76, 175, 80, 0.35);
}

.experiment-card--winning .experiment-card__header {
    border-bottom-color: rgba(76, 175, 80, 0.25);
}

.experiment-card__winning-badge {
    font-size: 0.75rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: #1b5e20;
    background: rgba(76, 175, 80, 0.35);
    padding: 4px 10px;
    border-radius: 6px;
}

.experiment-card__section {
    flex: 1;
}

.experiment-card__section-title {
    margin: 0 0 12px;
    font-size: 0.9rem;
    font-weight: 600;
    color: #c0c0c0;
    text-transform: uppercase;
    letter-spacing: 0.04em;
}

.experiment-card__metrics {
    list-style: none;
    margin: 0;
    padding: 0;
}

.experiment-card__metrics li {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    padding: 6px 0;
    border-bottom: 1px solid rgba(255, 255, 255, 0.06);
    font-size: 0.9rem;
}

.experiment-card__metrics li:last-child {
    border-bottom: none;
}

.experiment-card__metrics .metric-label {
    color: #a8a8a8;
}

.experiment-card__metrics .metric-value {
    font-weight: 600;
    color: #d0d0d0;
}

@media screen and (max-width: 900px) {
    .experiments-page {
        padding: 0 16px 16px;
    }

    .experiments-grid {
        grid-template-columns: 1fr;
    }
}
